alter table public.posts enable row level security;

-- Helper function to check if two users are friends
create or replace function public.is_friends(user1 uuid, user2 uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = user1 and addressee_id = user2)
    or (requester_id = user2 and addressee_id = user1)
    and status = 'accepted'
  );
$$;

-- Policy for R1, R2, R3, R4, R5: Managing Friendships
-- Users can read if they are involved in the relationship (requester or addressee)
-- Users can insert if they are the requester and the status is set to pending
-- Users can update only the addressee of a pending request (to accept), or either party to delete (status change logic handled by app or specific checks, here we allow delete which is often an update or insert/delete combo. Per R4/R5, only addressee can accept. Requesters cannot accept. Either can delete).
-- Note: RLS on status is tricky. We allow updates only for specific actions.
-- Accept: addressee updates status to 'accepted'.
-- Delete/Cancel: Either party can update to remove the record (usually done via insert({status:'deleted'}) or update. Let's assume standard update for status change to 'deleted' or similar, but R4 says "nothing else... can be changed".
-- To simplify and strictly follow R4/R5:
-- 1. Read: Self involved.
-- 2. Insert: Only requester (status becomes 'pending').
-- 3. Update: Only addressee if status is 'pending' (to accept). OR Either party if status is not 'pending' (to delete/cancel).
create policy "Allow managed users to manage friendships" on public.friendships
for all
using (
  auth.uid() = requester_id OR auth.uid() = addressee_id
)
with check (
  -- Insert: Must be requester, status must be pending (enforced by trigger or default, but check ensures intent)
  (auth.uid() = requester_id AND (
    (NOT EXISTS (SELECT 1 FROM public.friendships WHERE requester_id = auth.uid() AND addressee_id = auth.uid() OR requester_id = auth.uid() AND addressee_id = (SELECT addressee_id FROM public.friendships WHERE requester_id = auth.uid() LIMIT 1)) OR -- Simplified check logic: ensure we are creating a new one or updating own status if allowed
     -- Actually, simpler: Insert only allowed if requester.
     true
  ))
  -- Update: 
  -- If status is pending: Only addressee can change it (to accepted).
  -- If status is not pending (e.g. deleted or we allow deletion via update): Either party.
  (
    (status = 'pending' AND auth.uid() = addressee_id)
    OR
    (status != 'pending' AND (auth.uid() = requester_id OR auth.uid() = addressee_id))
  )
)
with check (
  -- Ensure requester != addressee
  requester_id <> addressee_id
);

-- More precise Update policy to strictly follow R4 (only addressee accepts) and R5 (either deletes)
-- We split Insert and Update for clarity if the above with check is too complex for the specific "pending" flow, but a single policy works if logic is sound.
-- Let's refine the With Check for Update:
drop policy if exists "Allow managed users to manage friendships" on public.friendships;
create policy "Allow managed users to manage friendships" on public.friendships
for select
  using (auth.uid() = requester_id OR auth.uid() = addressee_id);

create policy "Allow requester to send friend requests" on public.friendships
for insert
with check (
  auth.uid() = requester_id AND requester_id <> addressee_id
);

create policy "Allow addressee to accept friend requests" on public.friendships
for update
using (
  status = 'pending' AND auth.uid() = addressee_id
);

create policy "Allow either party to delete friendships" on public.friendships
for update
using (
  status != 'pending' AND (auth.uid() = requester_id OR auth.uid() = addressee_id)
);

-- Policy for R1, R2, R5: Managing Posts
create policy "Users can read posts based on audience and friendship" on public.posts
for select
using (
  -- Own posts
  author_id = auth.uid()
  OR
  -- Public posts
  audience = 'public'
  OR
  -- Friends posts
  (audience = 'friends' AND public.is_friends(auth.uid(), author_id))
);

create policy "Users can write only their own posts" on public.posts
for insert
with check (
  author_id = auth.uid()
);

create policy "Users can edit only their own posts" on public.posts
for update
using (
  author_id = auth.uid()
);

create policy "Users can delete only their own posts" on public.posts
for delete
using (
  author_id = auth.uid()
);

