set search_path = public
as $$
begin
  if (tg_op = 'DELETE') then
    if (old.legal_hold) then
      raise exception 'Cannot delete file under legal hold';
    end if;
  end if;

  if (tg_op = 'UPDATE') then
    if (old.legal_hold) then
      raise exception 'Cannot modify file under legal hold';
    end if;

    if (new.legal_hold = true) then
      raise exception 'Cannot set legal hold via app';
    end if;
  end if;

  if (tg_op = 'INSERT') then
    if (new.legal_hold = true) then
      raise exception 'Cannot set legal hold via app';
    end if;
  end if;

  return new;
end;
