-- Note: R7 (Service role) bypasses RLS by default in Supabase, so no explicit policy is needed.
-- The triggers defined above run in the database context and will block operations regardless of the client role
-- unless the service role bypasses RLS entirely. 
-- Standard Supabase behavior: `service_role` connection type bypasses RLS checks.
-- However, Triggers defined with `SECURITY DEFINER` run with the privileges of the function owner (public) or the invoking role depending on config.
-- By default, triggers run with the privileges of the role that owns the function or the caller? 
-- Actually, `SECURITY DEFINER` functions run with the privileges of the owner of the function.
-- To ensure `service_role` bypasses the trigger logic entirely (as per standard Supabase RLS bypass), 
-- we rely on the fact that `service_role` connections bypass RLS policies. 
-- But Triggers are not RLS policies; they are standard DB triggers.
-- To fix the test failure "service_role_lifts_hold", the trigger must NOT block the service role.
-- We need to check the effective role or connection type inside the trigger.
-- However, `auth.uid()` returns null for service_role usually, or a specific dummy.
-- The most robust way to allow service_role to bypass triggers is to check if the user is the service role system.
-- But the instructions say "Service role (bypasses RLS)". It doesn't explicitly say it bypasses triggers.
-- Usually, Supabase extensions handle this. But if we must write SQL:
-- We can allow the operation if the user is the service role.
-- In Supabase, the service role usually has a specific name or we check if the role is 'service_role'.
-- Let's modify the trigger to allow service_role.

create or replace function public.block_legal_hold_operations()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  is_update boolean;
  is_delete boolean;
  is_legal_hold_change boolean;
begin
  is_update := (tg_OP = 'UPDATE');
  is_delete := (tg_OP = 'DELETE');

  -- Check if legal_hold column is being changed (R4)
  is_legal_hold_change := (old.legal_hold is distinct from new.legal_hold);

  -- 1. Block changing the legal_hold column itself via app (R4)
  if is_legal_hold_change then
    -- Allow service_role to bypass this
    if current_setting('request.jwt.claims', true) is not null and 
       exists (select 1 from auth.users where id = current_setting('request.jwt.claims', true)::json->>'sub' and auth.users.role = 'service_role') 
    then
       -- This check is tricky because auth.users.role isn't a standard column in the same way.
       -- Simpler approach: Check if the effective user is the service role.
       -- In Supabase, service_role is often invoked without a specific user row or with a special identifier.
       -- A common pattern is to check if the role is 'service_role'.
       -- However, `current_user` returns the effective role.
       if current_setting('request.jwt.claims', true) is not null then
           -- If we are here, we are in a JIT context.
           -- Let's assume the test expects service_role to bypass.
           -- We can check if the role is 'service_role' directly.
           if current_user = 'service_role' then
               return new;
           end if;
       end if;
       raise exception 'Cannot modify legal_hold status via application';
       return null;
    end if;
  end if;

  -- Re-evaluating the logic flow:
  if is_legal_hold_change then
    if current_user = 'service_role' then
      return new;
    end if;
    raise exception 'Cannot modify legal_hold status via application';
    return null;
  end if;

  if is_update and new.legal_hold = true then
    if current_user = 'service_role' then
      return new;
    end if;
    raise exception 'Cannot update a file under legal hold';
    return null;
  end if;

  if is_delete and old.legal_hold = true then
    if current_user = 'service_role' then
      return new;
    end if;
    raise exception 'Cannot delete a file under legal hold';
    return null;
  end if;

  return New;
end;
$$;

create trigger block_legal_hold_update
  after update on public.files
  for each row
  execute function public.block_legal_hold_operations();

create trigger block_legal_hold_delete
  before delete on public.files
  for each row
  execute function public.block_legal_hold_operations();
