create or replace function public.check_sso_requirement(org_id bigint)
returns boolean as $$
declare
  requires_sso boolean;
  has_sso boolean;
begin
  select require_sso into requires_sso from public.orgs where id = org_id;
  if requires_sso is null then return true; end if;

  -- Check if any method in amr array is 'sso/saml'
  -- Assuming amr is a JSONB array of objects: [{"method": "..."}, ...]
  -- We use jsonb_path_exists to check if any object has method = 'sso/saml'
  has_sso := jsonb_path_exists(auth.jwt() -> 'amr', '$[*].method == "sso/saml"');

  return requires_sso = false or has_sso;
end;
$$ language plpgsql security definer;

