-- Enable RLS on all tables
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

-- Helper function to check SSO requirement
create or replace function public.check_sso_requirement(org_id bigint) returns boolean as $$
  declare
    requires_sso boolean;
  begin
    select require_sso into requires_sso from public.orgs where id = org_id;
    if requires_sso then
      return (
        select array_length((select jsonb_array_elements_text(auth.jwt()->'amr') as method), 1) >= 1
        and 
        exists (
          select 1 
          from jsonb_array_elements_text(auth.jwt()->'amr') as method 
          where method = 'sso/saml'
        )
      );
    else
      return true;
    end if;
  end;
$$ language plpgsql security definer;

-- Helper function to check user membership in an org
create or replace function public.is_member_of_org(user_id uuid, org_id bigint) returns boolean as $$
  begin
    return exists (
      select 1 from public.org_members 
      where org_id = org_id and user_id = user_id
    );
  end;
$$ language plpgsql security definer;

-- Helper function to check if user is an admin of an org
create or replace function public.is_admin_of_org(user_id uuid, org_id bigint) returns boolean as $$
  begin
    return exists (
      select 1 from public.org_members 
      where org_id = org_id and user_id = user_id and role = 'admin'
    );
  end;
$$ language plpgsql security definer;

-- Trigger to ensure no membership changes via app (Requirement R4)
-- This trigger will block any INSERT/UPDATE/DELETE on org_members except via service role if we wanted stricter control,
-- but since service_role bypasses RLS, we rely on RLS policies to restrict access for non-service roles.
-- However, the requirement says "Nobody can change memberships through the app". 
-- Since app uses anon/authenticated roles, we make org_members immutable for them.
create or replace function public.block_membership_changes() returns trigger as $$
  begin
    if current_setting('request.jwt.sub', true) is not null then
      -- We can't easily check if it's service role inside a trigger without context,
      -- but we can rely on RLS policies to deny access. 
      -- To strictly enforce "no app changes", we could block all non-service-role writes.
      -- But standard RLS policies handle the read/write permissions.
      -- Let's just return NOT NULL to allow the trigger to fire for auditing if needed, 
      -- but the actual blocking is done by RLS policies below which will deny anon/authenticated users.
      -- Actually, the cleanest way for R4 is to NOT have any policies that allow writes to org_members 
      -- for anon/authenticated roles. The policies below will do that.
    end if;
    return null; -- Prevent the trigger from altering the row, effectively making it read-only for policies that don't explicitly allow write
  end;
$$ language plpgsql;

-- RLS Policies

-- 1. Anonymous users cannot see or change anything (Requirement R5)
-- (Implicitly handled by default DENY, but we can be explicit if needed. Supabase defaults to deny all.)

-- 2. Organization members can see their organizations, the members of those organizations and their documents (Requirement R1)
--   For orgs with require_sso, only if amr contains 'sso/saml'.
create policy "members_view_orgs" on public.orgs
  for select
  using (
    exists (
      select 1 from public.org_members 
      where org_members.org_id = public.orgs.id and org_members.user_id = auth.uid()
    )
    and public.check_sso_requirement(public.orgs.id)
  );

create policy "members_view_org_members" on public.org_members
  for select
  using (
    org_members.user_id = auth.uid() 
    and public.check_sso_requirement(org_members.org_id)
  );

create policy "members_view_org_documents" on public.org_documents
  for select
  using (
    exists (
      select 1 from public.org_members 
      where org_members.org_id = public.org_documents.org_id and org_members.user_id = auth.uid()
    )
    and public.check_sso_requirement(public.org_documents.org_id)
  );

-- 3. Organization admins can create, edit and delete their organization's documents (Requirement R2)
--   Under the same session requirement (SSO if required).
create policy "admins_manage_documents" on public.org_documents
  for all
  using (
    (
      exists (
        select 1 from public.org_members 
        where org_members.org_id = public.org_documents.org_id and org_members.user_id = auth.uid() and org_members.role = 'admin'
      )
      or auth.jwt() ->> 'role' = 'service_role'
    )
    and public.check_sso_requirement(public.org_documents.org_id)
  );

-- 4. Organization admins can change their organization's settings (Requirement R3)
--   Under the same session requirement.
create policy "admins_manage_org_settings" on public.orgs
  for all
  using (
    (
      exists (
        select 1 from public.org_members 
        where org_members.org_id = public.orgs.id and org_members.user_id = auth.uid() and org_members.role = 'admin'
      )
      or auth.jwt() ->> 'role' = 'service_role'
    )
    and public.check_sso_requirement(public.orgs.id)
  );

-- 5. Nobody can change memberships through the app (Requirement R4)
--   We explicitly deny INSERT, UPDATE, DELETE on org_members for anon and authenticated roles.
--   Reads are allowed for members (as per R1).
create policy "deny_membership_changes" on public.org_members
  for all
  to anon, authenticated
  using (false)
  with check (false);

-- 6. Service role keeps full access (Requirement R6)
--   Explicitly grant usage on all functions to service role to ensure helper functions work correctly
--   when called by service_role (though service_role bypasses RLS, it needs function permissions).
grant execute on function public.check_sso_requirement(bigint) to service_role;
grant execute on function public.is_member_of_org(uuid, bigint) to service_role;
grant execute on function public.is_admin_of_org(uuid, bigint) to service_role;
