-- The policies above handle the security. We just need to make sure the 'authenticated' role isn't blocked by default denials.
-- By default, RLS blocks all access for 'anon'. 'authenticated' users are allowed if the policy applies.
-- We explicitly grant all to authenticated to ensure they can execute queries that match the policies.
grant all on public.workouts to authenticated;
grant all on public.workout_sets to authenticated;

-- Service role has full access to bypass RLS for server-side code
grant all on public.workouts to service_role;
grant all on public.workout_sets to service_role;

-- Revoke all from anon to enforce R1 and R3 (Anonymous cannot see or change anything)
revoke all on public.workouts from anon;
revoke all on public.workout_sets from anon;
