using (
  auth.jwt() is not null 
  and not (auth.role() = 'service_role') -- Service role bypasses RLS, but explicit for clarity in logic if needed, though service_role bypasses.
  -- Actually, service_role bypasses RLS entirely. We only need to check for authenticated users here.
  and exists (select 1 from public.building_staff bs join public.units u on u.building_id = bs.building_id where u.id = public.units.id and bs.user_id = auth.uid())
