  create view public.support_customers as
  select 
    c.id,
    c.region,
    c.full_name,
    substr(c.email, 1, 1) || '***' || split_part(c.email, '@', 2) || '@' || split_part(c.email, '@', 2) || '@' || split_part(c.email, '@', 3) || '@' || split_part(c.email, '@', 4) as email_masked,
    '******' || substr(c.phone, length(c.phone) - 3) as phone_masked
  from public.customers c;
end;
$$ language plpgsql;

-- R5: Anonymous visitors cannot see anything
create policy "Anonymous users cannot see anything" on public.customers
  for select using (false)
