-- Enable RLS on tables
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

-- Helper function to check if auction is active
create or replace function public.is_auction_active(auction_id bigint)
returns boolean
language sql
stable
as $$
  select a.id = $1 and a.ends_at > now()
  from public.auctions a
  where a.id = $1;
$$;

-- Helper function to check if user is the seller
create or replace function public.is_user_seller(user_id uuid, auction_id bigint)
returns boolean
language sql
stable
as $$
  select a.seller_id = $1
  from public.auctions a
  where a.id = $2;
$$;

-- Helper function to check if user is the highest bidder
create or replace function public.is_user_highest_bidder(user_id uuid, auction_id bigint)
returns boolean
language sql
stable
as $$
  select b.bidder_id = $1
  from public.bids b
  where b.auction_id = $2 and b.amount = (select highest_bid from public.auctions where id = $2);
$$;

-- Helper function to check if bid amount is valid
create or replace function public.is_valid_bid_amount(auction_id bigint, amount numeric, user_id uuid)
returns boolean
language plpgsql
stable
as $$
declare
  v_starting_price numeric;
  v_highest_bid numeric;
  v_min_increment numeric;
  v_has_bids boolean;
begin
  select starting_price, highest_bid, min_increment, (count(*) > 0)
  into v_starting_price, v_highest_bid, v_min_increment, v_has_bids
  from public.auctions
  where id = auction_id;

  if not v_has_bids then
    return amount >= v_starting_price;
  else
    return amount > v_highest_bid + v_min_increment;
  end if;
end;
$$;

-- Policy R1: Signed-in users can see every auction
create policy "Users can view auctions"
on public.auctions
for select
using (auth.role() = 'authenticated');

-- Policy R1: Bidders can see their own bids
create policy "Users can view their own bids"
on public.bids
for select
using (auth.uid() = bidder_id);

-- Policy R1: Sellers can see every bid on their auctions
create policy "Sellers can view bids on their auctions"
on public.bids
for select
using (exists (select 1 from public.auctions a where a.id = auction_id and a.seller_id = auth.uid()));

-- Policy R2: Nobody can create, change or delete auctions or bids directly
-- (Implicitly handled by denying insert/update/delete for all roles except service_role)
-- Explicitly deny for clarity if needed, but default RLS denies if no allow policy exists.
-- We rely on the absence of create/update/delete policies for anon/authenticated.

-- Policy R6: Service role keeps full access (handled by service_role bypassing RLS, but good to be explicit if using specific roles)
-- No policy needed for service_role as it bypasses RLS by default.

-- RPC Function: place_bid
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions;
  v_new_highest_bid numeric;
  v_error text;
begin
  -- Check if user is signed in
  if auth.uid() is null then
    raise exception 'User must be signed in to place a bid';
  end if;

  -- Check if auction exists
  select * into v_auction
  from public.auctions
  where id = p_auction_id;

  if not found then
    raise exception 'Auction not found';
  end if;

  -- Check if auction is active
  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- Check if caller is the seller
  if v_auction.seller_id = auth.uid() then
    raise exception 'Sellers cannot place bids on their own auctions';
  end if;

  -- Check if bid amount is valid
  if not public.is_valid_bid_amount(p_auction_id, p_amount, auth.uid()) then
    raise exception 'Bid amount is too low';
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  -- Update the highest bid
  update public.auctions
  set highest_bid = p_amount
  where id = p_auction_id;

  return p_amount;
exception
  when others then
    v_error := sqlerrm;
    raise exception '%', v_error;
end;
$$;

-- Trigger to ensure data integrity if needed (optional, but good practice for complex logic)
-- Since the logic is in the RPC function, we don't need a trigger for the core functionality.
-- However, if we want to enforce constraints at the DB level for safety:
-- (No additional triggers needed as per requirements, relying on RPC function for business logic)
