-- Helper function to get user's role
create or replace function public.get_user_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select auth.jwt()->>'role'::text;
$$;

-- Policy R1: Signed-in users can see every auction
create policy "Auth users can view all auctions"
on public.auctions
for select
using ( auth.role() = 'authenticated' );

-- Policy R1: Sellers can see all their own bids, bidders can see their own bids
create policy "Users can view their own bids"
on public.bids
for select
using ( auth.uid() = bidder_id );

create policy "Sellers can view all bids on their auctions"
on public.bids
for select
using ( exists ( select 1 from public.auctions where auctions.id = bids.auction_id and auctions.seller_id = auth.uid() ) );

-- Policy R2: Nobody can create, change or delete auctions or bids directly
-- (Create and Update policies are omitted, Delete policies are omitted)
-- Only select policies are active, enforcing read-only access for non-service roles.

-- Function to handle bid placement logic
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions;
  v_current_highest_bid numeric;
  v_min_increment numeric;
  v_starting_price numeric;
  v_error text;
begin
  -- Check if auction exists
  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for share;

  if not found then
    raise exception 'Auction not found';
  end if;

  -- Check if auction has ended
  if v_auction.ends_at < now() then
    raise exception 'Auction has ended';
  end if;

  -- Check if caller is the seller
  if v_auction.seller_id = auth.uid() then
    raise exception 'Sellers cannot bid on their own auctions';
  end if;

  -- Check if user is signed in (handled by security definer, but explicit check for clarity if needed in non-definer contexts)
  -- Since this is security definer, auth.uid() works for the caller.
  -- However, we need to ensure the caller is authenticated. If not, auth.uid() might fail or return null depending on context.
  -- The requirement R4 says raise error if not signed in.
  -- In a security definer function, if the caller is anonymous, auth.uid() will raise an error if not handled, 
  -- but typically we rely on the caller being authenticated for any mutation. 
  -- Let's add an explicit check to be safe against unauthenticated calls if the client doesn't auto-handle it.
  if auth.uid() is null then
    raise exception 'User must be signed in to place a bid';
  end if;

  -- Determine current highest bid and min increment
  select highest_bid, min_increment into v_current_highest_bid, v_min_increment
  from public.auctions
  where id = p_auction_id;

  if v_current_highest_bid is null then
    v_current_highest_bid := 0;
  end if;

  -- Check amount validity
  if p_amount <= v_starting_price and v_current_highest_bid = 0 then
    -- No bids yet, must be above starting price
    raise exception 'Bid must be above starting price';
  elsif p_amount <= (v_current_highest_bid + v_min_increment) then
    -- Must be above current highest + increment
    raise exception 'Bid must be higher than current highest by at least the minimum increment';
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  -- Update the auction's highest bid
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return p_amount;
exception
  when others then
    -- Re-raise or handle specific errors. 
    -- For this implementation, we re-raise to stop the transaction.
    raise;
