```sql
-- Enable RLS on both tables
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

-- 1. Helper Function: Get current highest bid for an auction
-- Used by the trigger to validate new bids and update the auction table.
create or replace function public.get_current_highest_bid(p_auction_id bigint) returns numeric as $$
  select coalesce(highest_bid, 0)
  from public.auctions
  where id = p_auction_id;
$$ language sql stable;

-- 2. Trigger Function: Handles the logic for placing a bid
-- This function is called BEFORE INSERT on 'bids'. It enforces all business rules (R4).
-- If valid, it inserts the bid and updates the auction's highest_bid.
-- If invalid, it raises an exception (preventing the insert).
create or replace function public.handle_bid_insert() returns trigger as $$
declare
  v_auction_id bigint;
  v_amount numeric;
  v_min_increment numeric;
  v_current_highest numeric;
  v_starting_price numeric;
  v_required_amount numeric;
  v_auction_active boolean;
  v_is_seller boolean;
begin
  -- Retrieve auction details
  select id, min_increment, starting_price, coalesce(highest_bid, 0)
  into v_auction_id, v_min_increment, v_starting_price, v_current_highest
  from public.auctions
  where id = NEW.auction_id;

  -- Check if auction exists (R4)
  if not found then
    raise exception 'Auction not found';
  end if;

  -- Check if auction is active (R4)
  select ends_at > now() into v_auction_active
  from public.auctions
  where id = v_auction_id;

  if not v_auction_active then
    raise exception 'Auction has ended';
  end if;

  -- Check if caller is the seller (R4)
  select (seller_id = auth.uid()) into v_is_seller
  from public.auctions
  where id = v_auction_id;

  if v_is_seller then
    raise exception 'Sellers cannot place bids on their own auctions';
  end if;

  -- Validate bid amount logic (R4)
  if v_current_highest is null then
    -- No bids yet: Must meet or exceed starting price
    if NEW.amount < v_starting_price then
      raise exception 'Bid amount must be at least the starting price';
    end if;
  else
    -- Existing bids: Must exceed current highest by at least min_increment
    v_required_amount := v_current_highest + v_min_increment;
    if NEW.amount < v_required_amount then
      raise exception 'Bid amount must be at least the current highest bid plus the minimum increment';
    end if;
  end if;

  -- All checks passed: Perform the insert
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (NEW.auction_id, auth.uid(), NEW.amount, now());

  -- Update the auction's highest bid
  update public.auctions
  set highest_bid = NEW.amount
  where id = v_auction_id;

  return NEW;
exception
  when others then
    raise;
end;
$$ language plpgsql security definer;

-- 3. Trigger: Automatically calls the logic function on every INSERT
create trigger trigger_bids_insert
  before insert on public.bids
  for each row execute function public.handle_bid_insert();

-- 4. RLS Policies for 'auctions' table (R1, R2)
-- SELECT: Allow authenticated users to see all auctions (R1). Deny anonymous (R5).
create policy "authenticated_users_select_auctions"
  on public.auctions
  for select
  using (auth.role() = 'authenticated');

-- UPDATE/DELETE: Deny all direct modifications (R2).
create policy "deny_auctions_updates"
  on public.auctions
  for update
  using (false);

create policy "deny_auctions_deletes"
  on public.auctions
  for delete
  using (false);

-- 5. RLS Policies for 'bids' table (R1, R2, R3, R4, R5)
-- SELECT: 
--   - Users can see their own bids.
--   - Sellers can see all bids on their auctions.
--   - Others cannot see bids (unless they are sellers of the auction).
--   - Anonymous cannot see anything (R5).
create policy "authenticated_view_own_bids"
  on public.bids
  for select
  using (auth.uid() = bidder_id);

create policy "sellers_view_auction_bids"
  on public.bids
  for select
  using (exists (
    select 1 from public.auctions 
    where auctions.id = bids.auction_id and auctions.seller_id = auth.uid()
  ));

-- INSERT:
--   - Allow authenticated users. The trigger enforces all business rules (R4).
--   - This satisfies R2 (no direct SQL app creation without trigger enforcement) 
--     and R5 (anonymous blocked by policy check).
create policy "authenticated_insert_bids"
  on public.bids
  for insert
  with check (auth.role() = 'authenticated');

-- UPDATE/DELETE: Deny all modifications to bids (R2).
create policy "deny_bids_updates"
  on public.bids
  for update
