    -- Since we can't easily check bids table count without overhead, we assume if highest_bid is null it's the first
    -- However, the logic in requirements says: "below the starting price when there are no bids yet"
    -- We assume if highest_bid IS NULL, there are no bids.
    is_first_bid := (select highest_bid from public.auctions where id = p_auction_id) IS NULL;

    if is_first_bid then
      -- First bid must be above starting price
      if p_amount <= (select starting_price from public.auctions where id = p_auction_id) then
        raise exception 'Bid amount must be above the starting price';
