  if v_auction.seller_id = auth.uid() then
    raise exception 'Sellers cannot place bids on their own auctions';
  end if;

  -- Get current highest bid and min increment (R4)
  select highest_bid, min_increment into v_highest_bid, v_min_increment from public.auctions where id = p_auction_id;

  -- Validate amount against starting price or current highest bid + increment (R4)
  if v_highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'Bid amount must be at least the starting price';
    end if;
  else
    if p_amount <= v_highest_bid + v_min_increment then
      raise exception 'Bid amount must be higher than current highest bid plus minimum increment';
    end if;
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  -- Update the auction's highest bid
  update public.auctions
  set highest_bid = p_amount
  where id = p_auction_id;

  return p_amount;
end;
$$;

-- Grant execute on the function to authenticated users
grant execute on function public.place_bid(bigint, numeric) to authenticated;
